import json
from datetime import datetime

def evaluate_memory(memory_id, facts, memories, policies, updates):
    # Find the memory to evaluate
    memory = next((m for m in memories if m['id'] == memory_id), None)
    if memory is None:
        return None  # No such memory exists

    # Find all facts that support this memory
    supporting_facts = []
    for fact in facts:
        if memory['text'] in fact['text']:
            supporting_facts.append(fact)

    # Check if any update contradicts a supporting fact
    for update in updates:
        if update['observed'] > memory['observed']:
            continue  # Update is newer than memory, ignore it
        for fact in supporting_facts:
            if update['text'] in fact['text'] and update['text'] != fact['text']:
                # Update contradicts a supporting fact, mark memory for withdrawal
                return 'withdraw'

    # Check if any update replaces a supporting fact
    for update in updates:
        if update['observed'] > memory['observed']:
            continue  # Update is newer than memory, ignore it
        for fact in supporting_facts:
            if update['text'] in fact['text'] and update['text'] != fact['text']:
                # Update replaces a supporting fact, mark memory for recompute
                return 'recompute'

    # Check if any update contradicts the memory itself
    for update in updates:
        if update['observed'] > memory['observed']:
            continue  # Update is newer than memory, ignore it
        if update['text'] in memory['text']:
            # Update contradicts the memory itself, mark memory for withdrawal
            return 'withdraw'

    # If no updates contradict or replace supporting facts, mark memory for keep
    return 'keep'

def evaluate_memories(facts, memories, policies, updates):
    changes = {}
    for memory in memories:
        action = evaluate_memory(memory['id'], facts, memories, policies, updates)
        if action is not None:
            changes[memory['id']] = action
    return changes

def main():
    data = json.loads('''
    {
 "facts": [...],
 "memories": [...],
 "policies": [...],
 "updates": [...]
}
''')

    facts = data['facts']
    memories = data['memories']
    policies = data['policies']
    updates = data['updates']

    changes = evaluate_memories(facts, memories, policies, updates)
    print(json.dumps(changes, indent=4))

if __name__ == '__main__':
    main()
